CREATE OR REPLACE FUNCTION trip_private.set_first_game(p_trip uuid,p_game integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can choose the first game'; END IF; IF p_game IS NULL OR NOT EXISTS(SELECT 1 FROM public.game_catalog WHERE number=p_game) THEN RAISE EXCEPTION 'Choose a game'; END IF; UPDATE public.game_nights SET game_number=p_game WHERE trip_id=p_trip AND week_number=1 AND game_number IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Week 1 already has a game or schedule is missing'; END IF; INSERT INTO public.trip_play_state(trip_id,used_games) VALUES(p_trip,ARRAY[p_game]) ON CONFLICT(trip_id) DO UPDATE SET used_games=array_append(array_remove(trip_play_state.used_games,p_game),p_game); END $fn$;
CREATE OR REPLACE FUNCTION trip_private.spin_next_game(p_trip uuid) RETURNS TABLE(game_number integer,week_number integer,spin_time timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_week integer; v_game integer; v_used integer[]; v_now timestamptz := clock_timestamp(); BEGIN IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Not in this trip'; END IF; SELECT n.week_number INTO v_week FROM public.game_nights n WHERE n.trip_id=p_trip AND n.starts_at<=v_now ORDER BY n.starts_at DESC LIMIT 1; IF v_week IS NULL THEN RAISE EXCEPTION 'Wait for the first game night'; END IF; IF NOT EXISTS(SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=auth.uid() AND (m.role IN ('captain','co_captain') OR m.user_id=(SELECT n.host_id FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_week))) THEN RAISE EXCEPTION 'Only a leader or this week''s host can spin'; END IF; IF NOT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_week AND n.game_number IS NOT NULL) THEN RAISE EXCEPTION 'Choose this week''s game first'; END IF; INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT DO NOTHING; SELECT s.used_games INTO v_used FROM public.trip_play_state s WHERE s.trip_id=p_trip FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=v_week+1 AND n.game_number IS NULL) THEN RAISE EXCEPTION 'No unassigned next week'; END IF; IF cardinality(v_used)>=12 THEN v_used:='{}'; END IF; SELECT g.number INTO v_game FROM public.game_catalog g WHERE NOT(g.number=ANY(v_used)) ORDER BY random() LIMIT 1; UPDATE public.game_nights n SET game_number=v_game WHERE n.trip_id=p_trip AND n.week_number=v_week+1 AND n.game_number IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'No unassigned next week'; END IF; UPDATE public.trip_play_state s SET used_games=array_append(v_used,v_game),spin_game=v_game,spin_week=v_week+1,spin_at=v_now WHERE s.trip_id=p_trip; RETURN QUERY SELECT v_game,v_week+1,v_now; END $fn$;